<?php
$q=trim($_GET['q']??'');$where='1=1';$params=[];if($q!==''){$where='(u.email LIKE ? OR u.first_name LIKE ? OR u.last_name LIKE ? OR u.phone LIKE ?)';$like='%'.$q.'%';$params=[$like,$like,$like,$like];}
$s=db()->prepare("SELECT u.*,(SELECT COUNT(*) FROM orders o WHERE o.user_id=u.id) order_count,(SELECT COALESCE(SUM(grand_total),0) FROM orders o WHERE o.user_id=u.id AND o.status<>'cancelled') lifetime_value,(SELECT COUNT(*) FROM user_addresses a WHERE a.user_id=u.id) address_count FROM users u WHERE $where ORDER BY u.id DESC LIMIT 300");$s->execute($params);$rows=$s->fetchAll();
$guestCount=(int)db()->query("SELECT COUNT(DISTINCT customer_email) FROM orders WHERE user_id IS NULL")->fetchColumn();
?>
<div class="admin-page-head"><div><span class="eyebrow">MÜŞTERİ</span><h2>Müşteri Yönetimi</h2><p>Üyeler, sipariş sayıları, toplam harcama ve kayıtlı adresleri.</p></div><div class="admin-actions"><span class="summary-chip">Üye: <?=count($rows)?></span><span class="summary-chip">Misafir sipariş e-postası: <?=$guestCount?></span></div></div>
<section class="admin-card"><div class="admin-card-head"><form class="admin-searchbar" method="get"><input type="hidden" name="page" value="customers"><div class="search-control"><span>⌕</span><input name="q" value="<?=h($q)?>" placeholder="Ad, e-posta veya telefon"></div><button class="admin-btn dark">Ara</button></form></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Müşteri</th><th>Telefon</th><th>Sipariş</th><th>Toplam Harcama</th><th>Adres</th><th>Son Giriş</th><th>Kayıt</th><th>Durum</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><?=wy_empty('Müşteri bulunamadı','Arama ölçütünü değiştirin.')?></td></tr><?php endif;?><?php foreach($rows as $u):?><tr><td><div class="customer-cell"><span class="admin-avatar"><?=h(mb_substr($u['first_name'],0,1))?></span><div><b><?=h($u['first_name'].' '.$u['last_name'])?></b><small><?=h($u['email'])?></small></div></div></td><td><?=h($u['phone'])?></td><td><?=(int)$u['order_count']?></td><td><b><?=money($u['lifetime_value'])?></b></td><td><?=(int)$u['address_count']?></td><td><?=h($u['last_login_at']?date('d.m.Y H:i',strtotime($u['last_login_at'])):'—')?></td><td><?=h(date('d.m.Y',strtotime($u['created_at'])))?></td><td><span class="status <?=$u['is_active']?'active':'inactive'?>"><?=$u['is_active']?'Aktif':'Pasif'?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<div class="info-box"><b>Misafirden üyeliğe dönüşüm</b><p>Müşteri üye olmadan sipariş verebilir. Sipariş başarı ekranında yalnızca şifre oluşturarak üyeliğini tamamladığında sipariş ve adres kayıtları otomatik olarak kullanıcı hesabına bağlanır.</p></div>